using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}C("C01",()=>{var d=new CouponStore();d.Valid.Add("A");return new CouponService(d).Redeem("A");});C("C02",()=>{var d=new CouponStore();d.Valid.Add("A");var s=new CouponService(d);var wins=0;Parallel.For(0,100,_=>{if(s.Redeem("A"))Interlocked.Increment(ref wins);});return wins==1;});C("C03",()=>{var d=new CouponStore();d.Valid.Add("A");var s=new CouponService(d);Parallel.For(0,20,_=>s.Redeem("A"));return d.Audit.Count==1;});C("C04",()=>{var d=new CouponStore();d.Valid.Add("A");var a=new CouponService(d);var b=new CouponService(d);return new[]{Task.Run(()=>a.Redeem("A")),Task.Run(()=>b.Redeem("A"))}.Count(x=>x.Result)==1;});C("C05",()=>{var d=new CouponStore();return !new CouponService(d).Redeem("X")&&d.Audit.Count==0;});
